// Checks a Retell book_service_call request before anything is logged.
// Every result carries a `say` line the agent acts on.

// ---- config ----------------------------------------------------------------
const NEXT_STEPS = 'The office will reach out to confirm the appointment time.';
const FEE_LINE = "Just so you know, there's a $99 service call fee for the technician to come out. Is that okay?";
const COVERED_BRANDS = /^(lg|samsung|ge|general electric)\b/; // matched against the normalized brand
const FEE_SPOKEN = /\$\s?99\b|\bninety[\s-]?nine\b|\b99 dollars?\b/i;
const DEDUPE_DAYS = 30;
const FEE_YES = /\b(yes|yeah|yep|yup|sure|ok|okay|alright|all right|fine|go ahead|sounds good|that works|absolutely|of course|perfect)\b/i;
const NO_HOUSE_NUMBER = /no house number/i; // what the agent writes in notes when the caller can't give one
const FEE_NO = /\b(no|nope|not sure|too much|too expensive|can't afford|rather not|don't book)\b/i;
// ----------------------------------------------------------------------------

const body = $input.first().json.body || {};
const args = body.args || {};
const call = body.call || {};
const callId = String(call.call_id || '').trim();

const text = (v) => (v === undefined || v === null ? '' : String(v).trim());
const reply = (result, say, extra = {}) => [
  { json: { result, say, response: { result, say }, append_row: false, call_id: callId, ...extra } },
];
const list = (items) => (items.length < 2 ? items.join('') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`);

// 1. Required arguments
const jobType = text(args.job_type).toLowerCase();
if (jobType !== 'standard' && jobType !== 'warranty') {
  return reply('missing', 'Set job_type to standard or warranty, then try again.');
}
const LABELS = {
  caller_name: "the caller's name",
  phone: 'the best callback number',
  service_address: 'the service address',
  appliance_type: 'which appliance it is',
  brand: 'the brand',
  issue: "what's wrong with it",
};
const missing = Object.keys(LABELS).filter((k) => !text(args[k]));
if (missing.length) {
  return reply('missing', `Ask for ${list(missing.map((k) => LABELS[k]))}, then try again.`);
}

// The address needs a house number, unless the caller couldn't give one
if (!/\d/.test(text(args.service_address)) && !NO_HOUSE_NUMBER.test(text(args.notes))) {
  return reply('missing', 'Ask for the house number of the service address, then try again.');
}

// 2. Warranty brand
const brand = text(args.brand).toLowerCase().replace(/\./g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
if (jobType === 'warranty' && !COVERED_BRANDS.test(brand)) {
  return reply(
    'not_covered',
    "We only do warranty work for LG, Samsung and GE, so this can't be a warranty job. " +
      `Offer a standard visit instead: "${FEE_LINE}" Book it as a standard job only after a clear yes.`,
  );
}

// 3. Fee gate for standard jobs: accepted, and the agent actually said the fee
if (jobType === 'standard') {
  const accepted = args.fee_accepted === true || text(args.fee_accepted).toLowerCase() === 'true';
  const turns = Array.isArray(call.transcript_object) && call.transcript_object.length
    ? call.transcript_object.filter((t) => t && t.role).map((t) => ({ role: String(t.role).toLowerCase(), content: text(t.content) }))
    : text(call.transcript).split('\n').map((line) => /^\s*(agent|user)\s*:\s*(.*)$/i.exec(line)).filter(Boolean)
      .map((m) => ({ role: m[1].toLowerCase(), content: m[2] }));
  // The caller's answer to the last fee line: their turns until the agent speaks again.
  let lastFee = -1;
  turns.forEach((t, i) => { if (t.role === 'agent' && FEE_SPOKEN.test(t.content)) lastFee = i; });
  const answer = [];
  for (const t of turns.slice(lastFee + 1)) { if (t.role === 'agent') break; answer.push(t.content); }
  const said = answer.join(' ').replace(/\bno (problem|worries)\b/gi, '');
  // Only a clear yes counts: a no, a question or no answer at all means ask again.
  const yes = FEE_YES.test(said.replace(/\bnot sure\b/gi, ""));
  const agreed = lastFee >= 0 && yes && !FEE_NO.test(said);
  if (!accepted || !agreed) {
    return reply(
      'fee_required',
      `Before booking, tell the caller: "${FEE_LINE}" Book only after a clear yes, with fee_accepted set to true. ` +
        "If they say no or aren't sure, don't book.",
    );
  }
}

// 4. Same call booked already: an identical repeat writes no row, changed details write a correction row
const store = $getWorkflowStaticData('global');
const booked = (store.bookedCalls = store.bookedCalls || {});
const cutoff = Date.now() - DEDUPE_DAYS * 24 * 60 * 60 * 1000;
const stamp = (entry) => (typeof entry === 'number' ? entry : (entry && entry.at) || 0);
for (const id of Object.keys(booked)) if (stamp(booked[id]) < cutoff) delete booked[id];
const details = JSON.stringify([jobType, ...Object.keys(LABELS).map((k) => text(args[k]).toLowerCase()), text(args.notes)]);
const earlier = callId ? booked[callId] : undefined;
if (earlier && earlier.details === details) {
  return reply('booked', NEXT_STEPS, { duplicate: true });
}
if (callId) booked[callId] = { at: Date.now(), details };
const notes = earlier ? `Correction of an earlier booking in this call. ${text(args.notes)}`.trim() : text(args.notes);

// 5. Booked
return reply('booked', NEXT_STEPS, {
  append_row: true,
  row: {
    logged_at: new Date().toISOString(),
    call_id: callId,
    job_type: jobType,
    caller_name: text(args.caller_name),
    phone: text(args.phone),
    service_address: text(args.service_address),
    appliance: text(args.appliance_type),
    brand: text(args.brand),
    issue: text(args.issue),
    fee_accepted: jobType === 'warranty' ? 'n/a (warranty)' : 'yes',
    notes,
  },
});
